import os
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def _read_note(name: str) -> str | None:
    """Return the text of the file `name` inside `notes`, or None if it is
    missing, unreadable, not a regular file, or resolves outside `notes`
    (via `..`, an absolute path, a symlink, or a NUL byte)."""
    if "\x00" in name or os.path.isabs(name):
        return None
    try:
        root = Path(NOTES_DIR).resolve()
        target = (root / name).resolve()
        if not target.is_relative_to(root):
            return None
        if not target.is_file():
            return None
        with target.open("r", encoding="utf-8", errors="replace") as f:
            return f.read()
    except (OSError, ValueError, RuntimeError):
        return None


def count_readable(names: list[str]) -> int:
    """Count the entries of `names` (duplicates counted each time) that are
    regular files readable from the directory `notes` relative to the working
    directory, including files in subdirectories such as `sub/b.txt`.
    Missing, unreadable, directory, or escaping names do not count, and no
    file outside `notes` is ever read."""
    return sum(1 for name in names if _read_note(name) is not None)


@pytest.fixture
def notes(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    root = tmp_path / "notes"
    (root / "sub" / "deep").mkdir(parents=True)
    (root / "a.txt").write_text("alpha")
    (root / "empty.txt").write_text("")
    (root / "sub" / "b.txt").write_text("beta")
    (root / "sub" / "deep" / "c.txt").write_text("gamma")
    (tmp_path / "secret.txt").write_text("secret")
    (tmp_path / "notes_evil").mkdir()
    (tmp_path / "notes_evil" / "x.txt").write_text("x")
    monkeypatch.chdir(tmp_path)
    return root


def test_empty_list(notes: Path) -> None:
    assert count_readable([]) == 0


def test_top_level_files(notes: Path) -> None:
    assert count_readable(["a.txt"]) == 1
    assert count_readable(["a.txt", "empty.txt"]) == 2


def test_subdirectory_files(notes: Path) -> None:
    assert count_readable(["sub/b.txt", "sub/deep/c.txt"]) == 2


def test_missing_files(notes: Path) -> None:
    assert count_readable(["nope.txt", "sub/nope.txt", "nodir/a.txt"]) == 0


def test_mixed(notes: Path) -> None:
    assert count_readable(["a.txt", "nope.txt", "sub/b.txt"]) == 2


def test_duplicates_counted_each(notes: Path) -> None:
    assert count_readable(["a.txt", "a.txt"]) == 2


def test_directories_not_counted(notes: Path) -> None:
    assert count_readable(["sub", "sub/", "sub/deep", ".", "", "./"]) == 0


def test_parent_traversal_rejected(notes: Path) -> None:
    assert count_readable(["../secret.txt"]) == 0
    assert count_readable(["sub/../../secret.txt"]) == 0
    assert count_readable(["sub/deep/../../../secret.txt"]) == 0
    assert count_readable(["../notes/../secret.txt"]) == 0


def test_sibling_prefix_directory_rejected(notes: Path) -> None:
    assert count_readable(["../notes_evil/x.txt"]) == 0


def test_absolute_path_outside_rejected(notes: Path) -> None:
    outside = str(notes.parent / "secret.txt")
    assert count_readable([outside]) == 0
    assert count_readable(["/etc/passwd"]) == 0


def test_absolute_path_not_treated_as_relative_escape(notes: Path) -> None:
    assert count_readable(["//" + str(notes.parent / "secret.txt")]) == 0


def test_dotdot_staying_inside_is_ok(notes: Path) -> None:
    assert count_readable(["sub/../a.txt"]) == 1


def test_symlink_file_escaping_rejected(notes: Path) -> None:
    os.symlink(notes.parent / "secret.txt", notes / "link.txt")
    assert count_readable(["link.txt"]) == 0


def test_symlink_dir_escaping_rejected(notes: Path) -> None:
    os.symlink(notes.parent, notes / "up")
    assert count_readable(["up/secret.txt"]) == 0
    assert count_readable(["up/notes_evil/x.txt"]) == 0
    # Loops back to a file that really lives inside notes: allowed.
    assert count_readable(["up/notes/a.txt"]) == 1


def test_symlink_inside_notes_ok(notes: Path) -> None:
    os.symlink(notes / "a.txt", notes / "alias.txt")
    assert count_readable(["alias.txt"]) == 1


def test_nul_byte_name(notes: Path) -> None:
    assert count_readable(["a.txt\x00.png", "\x00"]) == 0


def test_very_long_name(notes: Path) -> None:
    assert count_readable(["a" * 10000]) == 0


@pytest.mark.skipif(
    os.name != "posix" or (hasattr(os, "geteuid") and os.geteuid() == 0),
    reason="permission bits not enforced",
)
def test_unreadable_file_not_counted(notes: Path) -> None:
    locked = notes / "locked.txt"
    locked.write_text("x")
    locked.chmod(0)
    try:
        assert count_readable(["locked.txt", "a.txt"]) == 1
    finally:
        locked.chmod(0o644)


def test_missing_notes_directory(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    (tmp_path / "secret.txt").write_text("s")
    monkeypatch.chdir(tmp_path)
    assert count_readable(["a.txt", "../secret.txt"]) == 0


def test_read_note_contents(notes: Path) -> None:
    assert _read_note("a.txt") == "alpha"
    assert _read_note("sub/b.txt") == "beta"
    assert _read_note("empty.txt") == ""
    assert _read_note("missing.txt") is None
    assert _read_note("../secret.txt") is None
    assert _read_note("sub") is None

